// ─── File: src/main/java/com/bank/convert/model/Payment.java ───
package com.bank.convert.model;

import com.fasterxml.jackson.dataformat.xml.annotation.*;
import java.math.BigDecimal;

// One typed object binds to BOTH JSON and XML. Money stays BigDecimal in both.
@JacksonXmlRootElement(localName = "payment")
public class Payment {

    // id becomes an XML attribute <payment id="..."> and a JSON field "id".
    @JacksonXmlProperty(isAttribute = true)
    private String id;

    @JacksonXmlProperty(localName = "amount")
    private BigDecimal amount;

    @JacksonXmlProperty(localName = "currency")
    private String currency;

    @JacksonXmlProperty(localName = "beneficiary")
    private String beneficiary;

    public Payment() { }

    public String getId() { return id; }
    public void setId(String id) { this.id = id; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public String getCurrency() { return currency; }
    public void setCurrency(String currency) { this.currency = currency; }
    public String getBeneficiary() { return beneficiary; }
    public void setBeneficiary(String beneficiary) { this.beneficiary = beneficiary; }
}
```

