package com.bank.convert.service;

import com.bank.convert.model.Payment;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

// Type-safe conversion: both formats go through the same Payment object,
// so the amount stays a BigDecimal and the id stays an XML attribute.
@Service
public class PaymentConverter {

    private static final Logger log = LoggerFactory.getLogger(PaymentConverter.class);
    private final XmlMapper xmlMapper = new XmlMapper();
    private final ObjectMapper jsonMapper = new ObjectMapper();

    public String xmlToJson(String xml) throws Exception {
        Payment payment = xmlMapper.readValue(xml, Payment.class);   // XML → object
        String json = jsonMapper.writeValueAsString(payment);        // object → JSON
        log.info("Converted XML to JSON for payment {}", payment.getId());
        return json;
    }

    public String jsonToXml(String json) throws Exception {
        Payment payment = jsonMapper.readValue(json, Payment.class);  // JSON → object
        String xml = xmlMapper.writeValueAsString(payment);           // object → XML
        log.info("Converted JSON to XML for payment {}", payment.getId());
        return xml;
    }
}
```

