// ─── File: src/main/java/com/bank/convert/service/QuickConverter.java ───
package com.bank.convert.service;

import org.json.JSONObject;
import org.json.XML;
import org.springframework.stereotype.Service;

// Lightweight structural conversion — no Java class needed, but lossy about
// attributes and number-vs-string. Good for quick admin tooling only.
@Service
public class QuickConverter {

    public String xmlToJson(String xml) {
        JSONObject obj = XML.toJSONObject(xml);
        return obj.toString(2);          // pretty-printed JSON
    }

    public String jsonToXml(String json) {
        JSONObject obj = new JSONObject(json);
        return XML.toString(obj);
    }
}
```

