// ─── File: src/main/java/com/bank/convert/controller/ConvertController.java ───
package com.bank.convert.controller;

import com.bank.convert.service.PaymentConverter;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/convert")
public class ConvertController {

    private final PaymentConverter converter;

    public ConvertController(PaymentConverter converter) {
        this.converter = converter;
    }

    @PostMapping(value = "/xml-to-json", consumes = "application/xml", produces = "application/json")
    public String toJson(@RequestBody String xml) throws Exception {
        return converter.xmlToJson(xml);
    }

    @PostMapping(value = "/json-to-xml", consumes = "application/json", produces = "application/xml")
    public String toXml(@RequestBody String json) throws Exception {
        return converter.jsonToXml(json);
    }
}
```
